#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long total = 0;
    for (int bit = 0; bit < 60; bit++) {
        long long c = 0;
        for (long long x : a) c += (x >> bit) & 1;
        total += c * (n - c);
    }
    cout << total << "\n";

    return 0;
}

